# Inventory collected from actual emitted markup; every component occurrence is enumerated.
from html.parser import HTMLParser
class Inv(HTMLParser):
 def __init__(self,page):super().__init__();self.page=page
 def handle_starttag(self,t,aa):
  a=dict(aa)
  if 'data-component' in a: inventory.setdefault(a['data-component'],[]).append({'page':self.page,'tag':t,'data_section':a['data-section'],'selector':f'{t}[data-section="{a["data-section"]}"][data-component="{a["data-component"]}"]'})
